import 'dart:convert';

import 'package:flutter/services.dart';

import '../models/offer_match.dart';

/// Small (about 20 KB) map from curated product id to a real store listing,
/// generated by `tool/match_fixtures.py` from the scraped store database.
///
/// Until [load] or [install] runs, nothing is matched and the optimiser uses
/// the fixture prices, so tests stay deterministic.
class OfferMatches {
  OfferMatches._();

  static Map<String, OfferMatch> _byProductId = const {};
  static int _revision = 0;

  static int get revision => _revision;
  static int get count => _byProductId.length;
  static OfferMatch? of(String productId) => _byProductId[productId];

  static Future<void> load({AssetBundle? bundle}) async {
    try {
      final raw = await (bundle ?? rootBundle).loadString(
        'assets/catalogue/matches.json',
      );
      final decoded = jsonDecode(raw) as Map<String, dynamic>;
      final matches = (decoded['matches'] as Map<String, dynamic>).map(
        (id, row) =>
            MapEntry(id, OfferMatch.fromJson(row as Map<String, dynamic>)),
      );
      install(matches);
    } catch (_) {
      // Missing or malformed asset: keep fixture prices.
      install(const {});
    }
  }

  static void install(Map<String, OfferMatch> matches) {
    _byProductId = Map.unmodifiable(matches);
    _revision++;
  }
}
